 void Bind(Binding b,Action<object> read){bindings.Add(b);List<Action<object>> list;if(!readers.TryGetValue(b.Key,out list)){list=new List<Action<object>>();readers[b.Key]=list;}list.Add(read);if(bindingOwner!=null)stripBindings[bindingOwner].Add(Tuple.Create(b,read));}
 void Track(Control c,params Binding[] refs){controlBindings[c]=refs.ToList();if(!deviceControls.Contains(c))deviceControls.Add(c);}
 void Queue(Binding b,object value){if(!UiAlive||refreshing||!EditorAccess||!backend.Connected||busy||reading||!b.Editable)return;try{b.Param.Validate(value);pending[b.Key]=Tuple.Create(b,value);message.Text="Enviando ajuste…";message.ForeColor=UITheme.Muted;}catch(Exception e){Error(e);}}
 async Task Flush(bool duringHandover=false){if(!UiAlive||flushing||busy&&!duringHandover||!backend.Connected||pending.Count==0)return;flushing=true;int epoch=revision;try{var changes=pending.Values.ToArray();pending.Clear();foreach(var c in changes){if(!UiAlive||epoch!=revision)break;await backend.Set(c.Item1,c.Item2);}if(UiAlive){message.Text=preview?"Vista de diseño · los cambios son simulados.":"Ajustes enviados · guarda el preset para conservarlos.";}}catch(Exception e){pending.Clear();if(duringHandover)throw;Error(e);}finally{flushing=false;}}
 void Knobs(ParamStrip panel,string group,Asset asset,Func<Parameter,bool> filter,Color? accent=null){
  panel.SuspendLayout();
  List<Tuple<Binding,Action<object>>> retired;if(stripBindings.TryGetValue(panel,out retired))foreach(var pair in retired){bindings.Remove(pair.Item1);readers[pair.Item1.Key].Remove(pair.Item2);}
  stripBindings[panel]=new List<Tuple<Binding,Action<object>>>();
  foreach(Control old in panel.Controls.Cast<Control>().ToArray())old.Dispose();panel.Controls.Clear();
  foreach(Control c in controlBindings.Keys.Where(c=>c.IsDisposed).ToArray())controlBindings.Remove(c);
  deviceControls.RemoveAll(c=>c.IsDisposed);
  bindingOwner=panel;
  try{
  foreach(var p in asset.parameters.Where(filter)){
   if(group=="CatalystGroupAmp"&&p.id=="Boost"){panel.Controls.Add(BuildPreamp(group,asset));continue;}
   var b=new Binding(group,p,true,asset.role=="ampCategory"||asset.role=="fXCategory"||asset.role=="reverbCategory"?asset.id:null);if(p.choices!=null){var outer=new Panel{Width=104,Height=128,Margin=new Padding(3,3,3,1),BackColor=Color.Transparent};var label=LabelText(p.name,true);label.Location=new Point(3,10);outer.Controls.Add(label);var combo=Combo();combo.SetBounds(3,39,98,28);combo.Items.AddRange(p.choices);bool set=false;Bind(b,v=>{set=true;combo.SelectedIndex=Math.Max(-1,Math.Min(p.choices.Length-1,Convert.ToInt32(v)-(int)p.minimum));set=false;});combo.SelectedIndexChanged+=delegate{if(!set&&combo.SelectedIndex>=0)Queue(b,combo.SelectedIndex+(int)p.minimum);};outer.Controls.Add(combo);panel.Controls.Add(outer);Track(outer,b);
   }else{var knob=new Knob(b);knob.Accent=EditorColors.Group(group);knob.Edited+=Queue;if(p.id=="graphSlotAsset_TempoSyncSubDivision")namHelp.SetToolTip(knob,"Duración de la nota. T: tresillo; ·: puntillo.");panel.Controls.Add(knob);Bind(b,knob.Read);Track(knob,b);object v;if(values.TryGetValue(b.Key,out v))knob.Read(v);
   }
  }
  }finally{bindingOwner=null;PruneZoom();ScaleFreshControls(panel);panel.ResumeLayout(true);ScheduleSoundLayout();if(panel.Parent!=null)panel.Parent.Invalidate(true);}
 }
