 void ArrangeSound(bool beforeShow=false){if(arranging||EditorZoom.Applying||soundStack==null||effectGrid==null||!Visible&&!beforeShow||currentPage!=0||strips["amp"].Width<S(400))return;arranging=true;try{foreach(Control root in Controls)if(root.Dock==DockStyle.Fill&&root.Bounds!=ClientRectangle)root.Bounds=ClientRectangle;foreach(Control header in AllChildren(pages[0]).Where(c=>c.Name=="CardHeader")){int left=S(Convert.ToInt32(header.Tag));header.SetBounds(left,0,Math.Max(1,header.Parent.ClientSize.Width-left-S(8)),S(38));}int maxRows=1;foreach(var pair in strips){var panel=pair.Value;if(panel.Width<S(100)||panel.Controls.Count==0)continue;bool fx=pair.Key=="CatalystGroupEffect"||pair.Key=="CatalystGroupReverb";int columns=fx?Math.Min(6,panel.Controls.Count):panel.Controls.Count;int cellWidth=Math.Max(1,(panel.ClientSize.Width-panel.Padding.Horizontal)/columns);foreach(Control control in panel.Controls){if(fx)control.Margin=new Padding(S(2),S(3),S(2),S(1));bool ampStrip=pair.Key=="amp";if(ampStrip&&!(control is PreampPanel))control.Margin=new Padding(S(3),S(28),S(3),S(1));int span=ampStrip?(control is PreampPanel?S(220):Math.Max(1,(panel.ClientSize.Width-panel.Padding.Horizontal-S(220))/Math.Max(1,panel.Controls.Count-1))):cellWidth;int width=Math.Max(1,span-control.Margin.Horizontal);if(control.Width!=width)control.Width=width;var preamp=control as PreampPanel;if(preamp!=null&&preamp.ArrangeControls!=null)preamp.ArrangeControls();}if(fx)maxRows=Math.Max(maxRows,(panel.Controls.Count+columns-1)/columns);else if(pair.Key=="amp"){panel.Height=panel.Controls.Cast<Control>().Max(c=>c.Height+c.Margin.Vertical)+panel.Padding.Vertical;panel.Parent.Height=panel.Height+S(46);}}
   namCaption.Width=Math.Max(S(100),strips["amp"].Parent.Width-S(470));int stripHeight=S(maxRows*132+4);foreach(string group in new[]{"CatalystGroupEffect","CatalystGroupReverb"}){var panel=strips[group];panel.Height=stripHeight;panel.Parent.Height=stripHeight+S(46);}effectGrid.Height=stripHeight+S(52);
