 void Toggle(Control parent,Binding b,string caption,bool topRight=false){var c=new CheckBox{Text=caption,AutoSize=true,Font=UITheme.Bold,ForeColor=UITheme.Success,BackColor=Color.Transparent,Margin=new Padding(8)};bool set=false;Bind(b,v=>{set=true;c.Checked=Convert.ToBoolean(v);set=false;});c.CheckedChanged+=delegate{if(!set)Queue(b,b.Param.kind=="bool"?(object)c.Checked:(object)(c.Checked?1:0));};parent.Controls.Add(c);if(topRight){c.Location=new Point(parent.Width-105,9);c.Anchor=AnchorStyles.Top|AnchorStyles.Left;parent.Resize+=delegate{c.Location=new Point(parent.Width-S(105),S(9));};}Track(c,b);}
 async Task ChangePreset(){if(!UiAlive)return;int bi=bank.SelectedIndex,ch=channel.SelectedIndex;await Run(async()=>{revision++;pending.Clear();await backend.SelectPreset(bi,ch);if(UiAlive)await RefreshDevice();});}
 async Task RefreshDevice(){if(!UiAlive||!backend.Connected||reading)return;reading=refreshing=true;resyncRequested=false;UpdateEnabled();try{readingModels=true;var first=bindings.Where(b=>b.Param.kind=="string"||b.Group=="systemState"||b.Param.kind=="strings").ToArray();await backend.Read(first);if(!UiAlive)return;readingModels=false;foreach(var pair in selectors){var a=pair.Value.SelectedItem as Asset;if(a!=null&&(!renderedAssets.ContainsKey(pair.Key)||renderedAssets[pair.Key]!=a.id)){RebuildGroup(pair.Key,a);renderedAssets[pair.Key]=a.id;}}var already=new HashSet<string>(first.Select(b=>b.Key));await backend.Read(bindings.Where(b=>!already.Contains(b.Key)).ToArray());if(UiAlive)RefreshAdvanced();}finally{readingModels=reading=refreshing=false;UpdateEnabled();}}
 void OnChanged(string g,string p,object v){if(!UiAlive)return;ObserveFirmwareAccess(g,p,v);string key=g+"/"+p;object previous;bool changed=!values.TryGetValue(key,out previous)||!object.Equals(previous,v);values[key]=v;if(!pending.ContainsKey(key)){List<Action<object>> list;if(readers.TryGetValue(key,out list)){bool old=refreshing;refreshing=true;try{foreach(var read in list.ToArray())read(v);}catch(Exception e){Log("Lectura no disponible: "+key+" · "+e.Message);}finally{refreshing=old;}}}
  if(g=="systemState"&&p=="engineInterfaceConnectedToDevice"&&!Convert.ToBoolean(v)&&!editorUSBReleased){revision++;pending.Clear();values.Clear();}
  if(g=="systemState"&&p=="presetDidChange"||changed&&!readingModels&&(p=="graphSlot_AssetEngineID"||g=="systemState"&&(p=="currentAmpBank"||p=="currentAmpChannel"))){revision++;pending.Clear();resyncRequested=true;}
  if(g=="systemState"&&p=="currentPresetDirtyState")presetStatus.Text=Convert.ToBoolean(v)?"Cambios sin guardar":"";if(p=="graphSlot_AssetEngineID"||g=="CFAssets")UpdateNamCaption();if(!reading&&(g=="systemState"||g=="CFAssets"||g=="CFPreamp"&&p=="type"||p=="graphSlot_AssetEngineID"||p=="BoostEnable"||p=="graphSlot_EnabledState"||p=="graphSlotAsset_TempoSyncActive"))UpdateEnabled();}
 bool Readable(Binding b){if(!values.ContainsKey(b.Key))return false;object preampType;if(b.Group=="CFPreamp"&&(!PreampCapability.Available(backend)||b.Param.id=="tone"&&values.TryGetValue("CFPreamp/type",out preampType)&&Convert.ToInt32(preampType)==0))return false;if(b.Param.id=="graphSlot_AssetEngineID")return true;object flag;if((b.Group=="CatalystGroupAmp"&&b.Param.id=="Boost"||b.Group=="CFPreamp"&&b.Param.id!="type")&&values.TryGetValue("CatalystGroupAmp/BoostEnable",out flag)&&!Convert.ToBoolean(flag))return false;if(b.Group=="CatalystGroupEffect"||b.Group=="CatalystGroupReverb"){object model;if(values.TryGetValue(b.Group+"/graphSlot_AssetEngineID",out model)){var a=catalog.Find(Convert.ToString(model));if(a!=null&&!a.parameters.Any(p=>p.id==b.Param.id))return false;}if(b.Param.parent=="graphSlotAsset_TempoSyncActive"&&values.TryGetValue(b.Group+"/graphSlotAsset_TempoSyncActive",out flag)){bool sync=Convert.ToBoolean(flag);if(b.Param.id=="graphSlotAsset_ManualTime"&&sync||b.Param.id=="graphSlotAsset_TempoSyncSubDivision"&&!sync)return false;}}return true;}
 void UpdateEnabled(){if(!UiAlive)return;foreach(var c in deviceControls)if(!c.IsDisposed){List<Binding> refs;bool enabled=EditorAccess&&backend.Connected&&!busy&&!reading&&!IsFirmwarePage(currentPage)&&(!controlBindings.TryGetValue(c,out refs)||refs.All(Readable));if(c.Enabled!=enabled)c.Enabled=enabled;}for(int i=0;i<nav.Count;i++)nav[i].Enabled=PageAllowed(i)&&!busy&&(firmware==null||!firmware.Busy);connect.Text=preview?"Vista previa":busy?"Operación en curso…":IsFirmwarePage(currentPage)?"Comprobar USB":backend.Connected?"Desconectar USB":"Conectar USB";connect.Enabled=!preview&&!busy&&(firmware==null||!firmware.Busy)&&(!IsFirmwarePage(currentPage)||firmware==null||firmware.DataView==null||!firmware.DataView.HasDataOwner);connect.Visible=!preview;UpdateFirmwareAccessHint();RefreshConnectionLabel();ScheduleRestrictedPage();}
 async Task Run(Func<Task> action){if(!UiAlive||busy)return;busy=true;UpdateEnabled();try{while(flushing&&UiAlive)await Task.Delay(20);if(UiAlive)await action();}catch(Exception e){Error(e);}finally{busy=false;UpdateEnabled();}}
 void Error(Exception e){if(!UiAlive)return;message.Text=e.Message;message.ForeColor=UITheme.Error;Log(e.ToString());}
 void Log(string text){if(!UiAlive||activity.IsDisposed||activity.Disposing)return;activity.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);}
 async void OnClosing(object sender,FormClosingEventArgs e){if(closing)return;if(closePending){e.Cancel=true;return;}if(initializing||busy||firmware!=null&&firmware.Busy){e.Cancel=true;message.Text="Espera a que termine la operación antes de cerrar.";return;}e.Cancel=true;closePending=true;bool watchPresence=presenceTimer.Enabled;writes.Stop();layoutTimer.Stop();presenceTimer.Stop();loadingTicker.Stop();loadingClock.Stop();revision++;pending.Clear();resyncRequested=false;try{if(firmware!=null)await firmware.CloseData();await backend.Disconnect();if(firmware!=null)firmware.Dispose();}catch(Exception error){closePending=false;if(UiAlive){writes.Start();if(watchPresence)presenceTimer.Start();Error(error);UpdateEnabled();}return;}backend.Changed-=OnChanged;backend.Status-=OnBackendStatus;closing=true;Close();}
 public void Snapshot(string path,int page){if(currentPage!=page)ShowPage(page);Application.DoEvents();using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
}
